-- [batch29] 菜单收敛配套：前端 navItems → DB core_menus 平台级种子补种
--
-- 背景：批 29 把侧栏一级菜单由 35 个业务域收敛为 10 个域组，并把各模块 navItems
-- 的侧栏可见入口收敛到核心操作项（449 → 166 可见）。本次收敛只调整呈现层
-- （showInSidebar），route path / 权限码 / 页面组件均未改动。
--
-- 本迁移同步 DB 种子，消除 audit_menu_consistency.py 报出的 orphan_FE：
--   补种 267 项（前端有、DB 平台级种子无）
--   修正 1 项 path 不一致（mes-work-stations）
--   对齐 2 项历史遗留（mes-work-orders 改名、scm-contracts 软删）
--
-- 幂等：组 ON CONFLICT DO NOTHING；菜单 ON CONFLICT (tenant_id, code) DO UPDATE。
-- 注意 core_menus 无 visible 列——侧栏可见性由 navItems.showInSidebar 决定，
-- 且 getSidebarNavItems 已在注册表层过滤，补种不会让已下沉项重新出现在侧栏。

BEGIN;

-- 1) 历史项对齐：重复登记与失效路由清理
-- mes-work-orders 与 mes-work-order 是同一功能的重复登记（后者已存在），软删复数那条
UPDATE mes.core_menus SET status = 'inactive', deleted_at = now(), updated_at = now()
WHERE tenant_id = '00000000-0000-0000-0000-000000000000' AND code = 'mes-work-orders' AND deleted_at IS NULL;

-- scm-contracts 指向 FE 已不存在的 /scm/contracts 路由（采购合同走 scm-purchase-contract），软删
UPDATE mes.core_menus SET status = 'inactive', deleted_at = now(), updated_at = now()
WHERE tenant_id = '00000000-0000-0000-0000-000000000000' AND code = 'scm-contracts' AND deleted_at IS NULL;

